import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"損","description":"周易集解 - 損","frontmatter":{"title":"損","description":"周易集解 - 損"},"headers":[],"relativePath":"zh/classics/jijie/041.md","filePath":"zh/classics/jijie/041.md"}'),l={name:"zh/classics/jijie/041.md"};function n(p,a,d,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="損" tabindex="-1">損 <a class="header-anchor" href="#損" aria-label="Permalink to “損”">​</a></h1><h2 id="損-1" tabindex="-1">損 <a class="header-anchor" href="#損-1" aria-label="Permalink to “損”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>損，有孚，元吉，無咎。可貞，利有攸往。曷之用？二簋可用享。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：緩必有所失，故受之以損。</p><p>崔憬曰：宥罪緩死，失之於僥倖，有損於政刑，故言緩必有所失，故受之以損者也。</p><p>鄭玄曰：艮為山，兌為澤。互體坤，坤為地。山在地上，澤在地下，澤以自損增山之高也。猶諸侯損其國之富以貢獻於天子，故謂之損矣。</p><p>虞翻曰：泰初之上，損下益上，以據二陰，故「有孚，元吉，無咎」。艮男居上，兌女在下，男女位正，故「可貞利有攸往」矣。</p><p>崔憬曰：曷，何也。言其道上行，將何所用，可用二簋而享也。以喻損下益上，惟在乎心，何必竭於不足而補有餘者也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：損，損下益上，其道上行。損而有孚，元吉，無咎。可貞。利有攸往。曷之用？二簋可用享。二簋應有時。損剛益柔有時。損益盈虛，與時偕行。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>蜀才曰：此本泰卦。</p><p>案：坤之上九，下處乾三。乾之九三，上升坤六。損下益上者也。陽德上行，故曰｢其道上行｣矣。</p><p>荀爽曰：謂損乾之三居上。孚，二陰也。</p><p>荀爽曰：居上據陰，故「元吉，無咎」，以未得位，嫌於咎也。</p><p>荀爽曰：少男在上，少女雖年尚幼，必當相承，故曰「可貞」。</p><p>荀爽曰：謂陽利往居上。損者，損下益上，故利往居上。</p><p>荀爽曰：二簋，謂上體二陰也。上為宗廟。簋者，宗廟之器，故可享獻也。</p><p>虞翻曰：時謂春秋也。損二之五，震二月，益正月，春也。損七月，兌八月，秋也。謂春秋祭祀，以時思之。艮為時，震為應，故「應有時」也。</p><p>虞翻曰：謂冬夏也。二五已易成益。坤為柔。謂損。益上之三成既濟，坎冬離夏。故「損剛益柔有時」。</p><p>虞翻曰：乾為盈，坤為虛，損剛益柔，故「損益盈虛」。謂泰初之上，損二之五，益上之時，變通趨時，故「與時偕行」。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：山下有澤，損。君子以懲忿窒欲。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：君子，泰乾。乾陽剛武，為忿。坤陰吝嗇，為欲。損乾之初成兌說，故懲忿。初上據坤，艮為止，故窒欲也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，祀事遄往，無咎，酌損之。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>虞翻曰：祀，祭祀。坤為事，謂二也。遄，速。酌，取也。二失正，初利二速往，合志於五，得正無咎，已得之應，故「遄往，無咎，酌損之」。《象》曰「上合志也」。祀，舊作巳也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：祀事遄往，尚合志也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：終成既濟，謂二上合志於五也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，利貞，徵凶，弗損，益之。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰：失位當之正，故利貞。徵，行也。震為徵，失正毀折，故不徵。之五則凶，二之五成益，小損大益，故｢弗損，益之｣矣。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：九二利貞，中以為志也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：動體離中，故｢為志也｣。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，三人行，則損一人。一人行，則得其友。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：泰乾三爻，為三人；震為行，故｢三人行｣。損初之上，故｢則損一人｣。</p><p>虞翻曰：一人謂泰初之上，損剛益柔，故｢一人行｣。兌為友，初之上，據坤應兌，故｢則得其友｣。言致一也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：一人行，三則疑也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：坎為疑，上益三成坎，故｢三則疑｣。</p><p>荀爽曰：一陽在上，則教令行。三陽在下，則民眾疑也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，損其疾，使遄有喜，無咎。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>虞翻曰：四，謂二也。四得位，遠應初。二疾上五，已得承之。謂二之五，三上復。坎為疾也。陽在五稱喜。故｢損其疾，使遄有喜｣。二上體觀，得正承五，故｢無咎｣矣。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：損其疾，亦可喜也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>蜀才曰：四當承上，而有初應，必上之所疑矣。初，四之疾也。宜損去其初，使上遄喜。</p><p>虞翻曰：二上之五，體大觀象，故｢可喜也｣。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，或益之十朋之龜，弗克違，元吉。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：謂二五已變成益，故｢或益之｣。坤數十，兌為朋，三上失位，三動離為龜。十謂神靈攝寶文筮山澤水火之龜也，故｢十朋之龜｣。三上易位，成既濟，故｢弗克違，元吉｣矣。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：六五元吉，自上佑也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：內柔外剛，龜之象也。又體兌艮，互有坤震。兌為澤龜，艮為山龜，坤為地龜，震為木龜，坤數又十，故曰｢十朋｣。朋，類也。六五處尊，損已奉上。人謀允葉，龜墨不違，故能延上九之祐，而來十朋之益。所以大吉也。</p><p>崔憬曰：或之者，疑之也。故用元龜。價值二十大貝，龜之最神貴者，以決之，不能違其益之義。故獲元吉。雙貝曰朋也。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，弗損，益之，無咎，貞吉。利有攸往，得臣無家。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：損上益三也。上失正，之三得位，故｢弗損，益之，無咎，貞吉｣。動成既濟，故｢大得志｣。</p><p>虞翻曰：謂三往之上，故｢利有攸往｣。二五已動成益，坤為臣。三變據坤，成家人，故曰｢得臣｣。動而應三，成既濟，則家人壞，故曰｢無家｣。</p><p>王肅曰：處損之極，損極則益，故曰不損，益之。非無咎也。為下所益，故｢無咎｣。據五應三，三陰上附，外內相應，上下交接，正之吉也。故｢利有攸往｣矣。剛陽居上，群下共臣，故曰｢得臣｣矣。得臣則萬方一軌，故｢無家｣也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：弗損，益之，大得志也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：謂二五已變，上下益三，成既濟定。離坎體正，故｢大得志｣。</p>',81)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
